15	        System.out.print("请输入矩阵的行数：");
16	        rowNumber = scanner.nextInt();
17	        System.out.print("请输入矩阵的列数：");
18	        colNumber = scanner.nextInt();
19	        matrix = new int[rowNumber][colNumber];
20	        System.out.println("请输入矩阵：");
21	        for(int row = 0; row < rowNumber; row ++) {
22	            for(int col = 0; col < colNumber; col ++) {
23	                matrix[row][col] = scanner.nextInt();
24	            }
25	        }
26	        convertToTriple();
27	        transposition();
28	    }
