30	    private static void convertToTriple() {
31	        for(int row = 0; row < rowNumber; row ++) {
32	            for(int col = 0; col < colNumber; col ++) {
33	                if(matrix[row][col] == 0) {
34	                    continue;
35	                }
36	                rawMatrix.add(new Triple(row, col, matrix[row][col]));
37	            }
38	        }
39	        System.out.println("\n原矩阵三元组如下：");
40	        for(Triple triple : rawMatrix) {
41	            System.out.println(triple.toString());
42	        }
43	        System.out.println();
44	    }
45	
46	    private static void transposition() {
47	        for(Triple triple : rawMatrix) {
48	            targetMatrix.add(new Triple(triple.getCol(), triple.getRow(), triple.getNumber()));
49	        }
50	        Collections.sort(targetMatrix, new TripleComparator());
51	        System.out.println("\n转置后矩阵三元组如下：");
52	        for(Triple triple : targetMatrix) {
53	            System.out.println(triple.toString());
54	        }
55	        System.out.println();
56	    }
57	}
